                stream,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            )
            .expect("write rejected-token response");
        }
    });
    (format!("http://127.0.0.1:{port}"), handle)
}

fn run_with(
    binary: &str,
    home: &std::path::Path,
    bin_dir: &std::path::Path,
    capture: &std::path::Path,
    server: &str,
    standalone: bool,
) -> Output {
    let token = bound_client_token("codex");
    let inherited_path = std::env::var_os("PATH").unwrap_or_default();
    let path = std::env::join_paths(
        std::iter::once(bin_dir.to_path_buf()).chain(std::env::split_paths(&inherited_path)),
    )
    .expect("compose PATH");
    let mut command = Command::new(binary);
    if !standalone {
        command.arg("with");
    }
    command
        .args([
            "--server", server, "--token", &token, "codex", "--", "--global", "hi",
        ])
        .env("HOME", home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("PATH", path)
        .env("CAPTURE_ARGS", capture.join("args"))
        .env("CAPTURE_HOME", capture.join("home"))
        .env("CAPTURE_CONFIG", capture.join("config"))
        .env("CAPTURE_MODEL_CATALOG", capture.join("model-catalog.json"))
        .env("CAPTURE_CODEX_HOME", capture.join("codex-home"))
        .env("CAPTURE_TOKEN", capture.join("token"))
        .env("CODEX_HOME", home.join("codex-state"))
        .output()
        .expect("run wrapper")
}

fn assert_codex_overlay_launch(standalone: bool) {
    let directory = tempfile::tempdir().expect("temporary test directory");
    let home = directory.path().join("home");
    let bin = directory.path().join("bin");
    let capture = directory.path().join("capture");
    let codex_home = home.join("codex-state");
    fs::create_dir_all(&codex_home).expect("create real Codex home");
    fs::create_dir_all(&capture).expect("create capture directory");
    let stale = std::env::temp_dir().join(format!(
        "link-assistant-router-with-4294967294-{}",
        directory
            .path()
            .file_name()
            .expect("temporary directory name")
            .to_string_lossy()
    ));
    fs::create_dir_all(&stale).expect("create stale wrapper directory");
    let original = concat!(
        "model_provider = \"user-owned\"\n",
        "model_catalog_json = \"/private/foreign-models.json\"\n",
        "model_reasoning_effort = \"xhigh\"\n",
        "personality = \"pragmatic\"\n",
        "\n[mcp_servers.memory]\n",
        "command = \"memory-server\"\n",
    );
    fs::write(codex_home.join("config.toml"), original).expect("seed real config");
    fake_codex(&bin);
    let (server, requests) = mock_router();

    let output = run_with(
        if standalone {
            env!("CARGO_BIN_EXE_with-router")
        } else {
            env!("CARGO_BIN_EXE_link-assistant-router")
        },
        &home,
        &bin,
        &capture,
        &server,
        standalone,
    );

    assert_eq!(
        output.status.code(),
        Some(23),
        "client status must propagate; stdout: {}; stderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stderr = launcher_diagnostics(&home, &output);
    assert!(stderr.contains("\"router_model_launch\""), "{stderr}");
    assert!(stderr.contains("\"state\":\"unpinned\""), "{stderr}");
    assert!(
        stderr.contains("\"substitution_allowed\":false"),
        "{stderr}"
    );
    assert!(
        stderr.contains(&format!("\"router_endpoint\":\"{server}\"")),
        "{stderr}"
    );
    assert_eq!(
        fs::read_to_string(codex_home.join("config.toml")).expect("read real config"),
        original,
        "temporary launch must not change the user's config"
    );
    let args = fs::read_to_string(capture.join("args"))
        .expect("captured argv")
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    let provider = args[1]
        .strip_prefix("model_provider=")
        .and_then(|value| serde_json::from_str::<String>(value).ok())
        .expect("process-local provider argument");
    assert!(provider.starts_with("link-assistant-run-"), "{provider}");
    assert_eq!(
        args,
        [
            "-c".to_string(),
            format!(
                "model_provider={}",
                serde_json::to_string(&provider).unwrap()
            ),
            "-c".to_string(),
            format!(
                "model_catalog_json={}",
                serde_json::to_string(
                    &args[3]
                        .strip_prefix("model_catalog_json=")
                        .and_then(|value| serde_json::from_str::<String>(value).ok())
                        .expect("managed catalog argument")
                )
                .expect("catalog path JSON")
            ),
            "-c".to_string(),
            format!(
                "model_providers.{provider}={{ name = \"OpenAI\", base_url = \"{server}/api/services/codex/v1\", wire_api = \"responses\", requires_openai_auth = true, supports_websockets = true, supports_standalone_web_search = true }}"
            ),
            "-c".to_string(),
            format!("chatgpt_base_url=\"{server}/api/services/codex/backend-api\""),
            "-c".to_string(),
            format!("experimental_realtime_ws_base_url=\"{server}/api/services/codex/v1\""),
            "-c".to_string(),
            format!(
                "experimental_realtime_webrtc_call_base_url=\"{server}/api/services/codex/v1\""
            ),
            "exec".to_string(),
            "--global".to_string(),
            "hi".to_string(),
        ]
    );
    let managed_catalog_bytes =
        fs::read(capture.join("model-catalog.json")).unwrap_or_else(|error| {
            panic!(
                "captured managed catalog: {error}; args={args:?}; stdout={}; stderr={}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            )
        });
    let managed_catalog: serde_json::Value =
        serde_json::from_slice(&managed_catalog_bytes).expect("valid managed catalog");
    assert_eq!(managed_catalog["models"][0]["slug"], "gpt-5.6-sol");
    assert_eq!(managed_catalog["models"].as_array().unwrap().len(), 1);
    assert_eq!(
        fs::read_to_string(capture.join("config")).expect("captured real config"),
        original,
        "Codex must read the caller's existing configuration"
    );
    assert_eq!(
        fs::read_to_string(capture.join("token")).expect("captured token"),
        format!("{}\n", bound_client_token("codex"))
    );
    let captured_home = fs::read_to_string(capture.join("home")).expect("captured HOME");
    assert_eq!(captured_home.trim(), home.to_string_lossy());
    let captured_codex_home =
        fs::read_to_string(capture.join("codex-home")).expect("captured CODEX_HOME");
    assert_eq!(captured_codex_home.trim(), codex_home.to_string_lossy());
    assert!(!stale.exists(), "a later run must sweep crash leftovers");
    assert_eq!(
        requests.join().expect("mock router thread").join(","),
        "/api/health,/api/management/tokens,/api/models"
    );
}

#[test]
fn interrupt_reaches_client_and_still_cleans_temporary_home() {
    let directory = tempfile::tempdir().expect("temporary test directory");
    let home = directory.path().join("home");
    let bin = directory.path().join("bin");
    let capture = directory.path().join("capture");
    fs::create_dir_all(&home).expect("create home");
    fs::create_dir_all(&capture).expect("create capture directory");
    fake_codex(&bin);
    let (server, requests) = mock_router();
    let token = bound_client_token("codex");
    let inherited_path = std::env::var_os("PATH").unwrap_or_default();
    let path =
        std::env::join_paths(std::iter::once(bin).chain(std::env::split_paths(&inherited_path)))
            .expect("compose PATH");
    let mut wrapper = Command::new(env!("CARGO_BIN_EXE_with-router"))
        .args(["--server", &server, "--token", &token, "codex", "wait"])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("PATH", path)
        .env("FAKE_WAIT", "1")
        .env("CAPTURE_ARGS", capture.join("args"))
        .env("CAPTURE_HOME", capture.join("home"))
        .env("CAPTURE_CONFIG", capture.join("config"))
        .env("CAPTURE_TOKEN", capture.join("token"))
        .env_remove("CODEX_HOME")
        .spawn()
        .expect("spawn wrapper");
    // Instrumented and highly parallel CI can spend more than two seconds
    // scheduling the wrapper before the fake client writes its start marker.
    // Keep this comfortably below the separate eight-second cleanup bound.
    for _ in 0..250 {
        if capture.join("home").exists() {
            break;
        }
        thread::sleep(Duration::from_millis(20));
    }
    assert!(capture.join("home").exists(), "client did not start");
    let signal = Command::new("kill")
        .args(["-INT", &wrapper.id().to_string()])
        .status()
        .expect("signal wrapper");
    assert!(signal.success());
    let status = wrapper
        .wait_timeout(Duration::from_secs(8))
        .expect("wait for interrupted wrapper")
        .unwrap_or_else(|| {
            wrapper.kill().expect("kill stuck wrapper");
            panic!("wrapper did not clean up after Ctrl-C");
        });
    assert_eq!(status.code(), Some(42));
    let router_home = fs::read_to_string(capture.join("home")).expect("captured HOME");
    // An ordinary Codex run keeps the caller's real home even when interrupted.
    assert!(std::path::Path::new(router_home.trim()).is_dir());
    assert_eq!(
        requests.join().expect("mock router thread").join(","),
        "/api/health,/api/management/tokens,/api/models"
    );
}

#[test]
fn global_undo_restores_exact_config_and_permissions() {
    let directory = tempfile::tempdir().expect("temporary test directory");
    let home = directory.path().join("home");
    let config_directory = home.join(".codex");
    let config = config_directory.join("config.toml");
    fs::create_dir_all(&config_directory).expect("create Codex home");
    let original = b"# user formatting stays exact\nmodel_provider='personal'\n";
    fs::write(&config, original).expect("seed config");
    fs::set_permissions(&config, fs::Permissions::from_mode(0o640)).expect("set original mode");
    let (server, health) = mock_router();
    let token = bound_client_token("codex");

    let configured = Command::new(env!("CARGO_BIN_EXE_link-assistant-router"))
        .args([
            "with", "--server", &server, "--token", &token, "--global", "codex",
        ])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env_remove("CODEX_HOME")
        .output()
        .expect("configure globally");
    assert!(
        configured.status.success(),
        "global setup failed: {}{}",
        String::from_utf8_lossy(&configured.stdout),
        String::from_utf8_lossy(&configured.stderr)
    );
    health.join().expect("mock router thread");
    assert_ne!(fs::read(&config).expect("configured config"), original);

    let undone = Command::new(env!("CARGO_BIN_EXE_link-assistant-router"))
        .args(["with", "--global", "--undo", "codex"])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env_remove("CODEX_HOME")
        .output()
        .expect("undo global setup");
    assert!(
        undone.status.success(),
        "global undo failed: {}{}",
        String::from_utf8_lossy(&undone.stdout),
        String::from_utf8_lossy(&undone.stderr)
    );
    assert_eq!(fs::read(&config).expect("restored config"), original);
    assert_eq!(
        fs::metadata(&config)
            .expect("restored metadata")
            .permissions()
            .mode()
            & 0o777,
        0o640
    );
    let leftovers = fs::read_dir(config_directory)
        .expect("read Codex home")
        .map(|entry| entry.expect("directory entry").file_name())
        .collect::<Vec<_>>();
    assert_eq!(leftovers, [std::ffi::OsString::from("config.toml")]);
}

#[test]
fn global_undo_refuses_to_overwrite_later_user_edits() {
    let directory = tempfile::tempdir().expect("temporary test directory");
    let home = directory.path().join("home");
    let config = home.join(".codex/config.toml");
    fs::create_dir_all(config.parent().expect("config parent")).expect("create Codex home");
    fs::write(&config, "model_provider = 'personal'\n").expect("seed config");
    let (server, health) = mock_router();
    let token = bound_client_token("codex");
    let configured = Command::new(env!("CARGO_BIN_EXE_with-router"))
        .args(["--server", &server, "--token", &token, "--global", "codex"])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env_remove("CODEX_HOME")
        .output()
        .expect("configure globally");
    assert!(configured.status.success());
    health.join().expect("mock router thread");
    let mut edited = OpenOptions::new()
        .append(true)
        .open(&config)
        .expect("open configured file");
    edited
        .write_all(b"# user edit after setup\n")
        .expect("append user edit");

    let undone = Command::new(env!("CARGO_BIN_EXE_with-router"))
        .args(["--global", "--undo", "codex"])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env_remove("CODEX_HOME")
        .output()
        .expect("attempt undo");
    assert!(!undone.status.success());
    assert!(String::from_utf8_lossy(&undone.stderr).contains("changed after it was configured"));
    let log = fs::read_to_string(home.join(".link-assistant-router/logs/operational.log"))
        .expect("explicit command failures persist alongside their results");
    assert!(log.contains("changed after it was configured"), "{log}");
    assert!(
        fs::read_to_string(config)
            .expect("read edited config")
            .contains("user edit after setup")
    );
}

